//****** transformations ******
mat3 scale_matrix(vec3 scale){
    return mat3(scale.x, 0, 0,
                0, scale.y, 0,
                0, 0, scale.z);
}
mat2 rotate_matrix(float angle){
    float c = cos(angle),
          s = sin(angle);
    return mat2(c, -s,
                s, c);
}
vec3 moveto(vec3 p, vec3 pos){
    p -= pos;
    return p;
}
vec3 rotate(vec3 p, float angel1, float angel2){
    p.yz *= rotate_matrix(angel2);
    p.xz *= rotate_matrix(angel1);
    return p;
}
float smin( float a, float b, float k ) {
    float h = clamp( 0.5+0.5*(b-a)/k, 0., 1. );
    return mix( b, a, h ) - k*h*(1.0-h);
}

