// ********* distance to an object *********
float sdPlane(vec3 p, Plane plane){
    // distance to the plane
    p -= plane.position;
    return dot(p, plane.normal);
}
float sdBox(vec3 p, Box box){
    // distance to the box
    // p = moveto(p, box.position);
    p -= box.position;

    vec3 pp = abs(p)-box.abc;
    return length(max(pp, 0.)) + min(max(pp.x, max(pp.y, pp.z)),0.);
}
float sdBox2D(vec3 p, Box box){
    // distance to the box
    // p = moveto(p, box.position);
    float edge = 0.2;
    float thickness = 0.05;

    p -= box.position;

    vec2 pp = abs(p.xy)-(box.abc.xy-edge);
    float dist = length(max(pp, 0.)) + min(max(pp.x, pp.y), 0.);

    return length(vec2(dist-edge, p.z)) - thickness;
}
float sdBoxRounded(vec3 p, Box box){
    // distance to the box
    // p = moveto(p, box.position);
    p -= box.position;
    float edge = 0.1;

    vec3 pp = abs(p)-box.abc;
    return length(max(pp, 0.)) + min(max(pp.x, max(pp.y, pp.z)),0.)
         - edge;
}
float sdSphere(vec3 p, Sphere sphere){
    // distance to the sphere (center - sphere radius)
    // scale object
    p -= sphere.position;
    // vec3 scale = vec3(1, 2, 0.5);
    vec3 scale = vec3(1., 1., 1.);
    // p *= scale_matrix(scale);
    p /= scale;
    return (length(p) - sphere.radius);
}
float sdLineSegment(vec3 p, vec3 a, vec3 b){
    vec3 ap = p - a, ab = b - a;
    float t = clamp(dot(ap, ab)/dot(ab,ab), 0., 1.);
    vec3 c = a + ab*t;

    float thickness = 0.01;
    return length(p-c) - thickness;
}
float sdBall(inout Material material, vec3 p, Sphere sphere, float angle){
    vec3 ring_pos = sphere.position + vec3(0, 0.15, 0);
    vec3 holder_pos = + vec3(sphere.position.x, box2.position.y+box2.abc.y + .0, box2.position.z-0.075);

    p -= holder_pos;
    p.xy *= rotate_matrix(radians(angle));
    p += holder_pos;

    // distance to the sphere (center - sphere radius)
    float d = sdSphere(p, sphere);

    //ring
    float d_ring = length(vec2(length(p.xy-ring_pos.xy) - .05, p.z)) -.01;

    d = min(d, d_ring);

    float d_line = sdLineSegment(vec3(p.xy, abs(p.z)), ring_pos, holder_pos);
    d = min(d, d_line);
    if (d == d_line)
        material = material_line;
    else
        material = sphere.material;
    return d;
}

// ********* get distance to the closest in an ensemble of objects *********
float GetDistance(inout Material material, vec3 p){
    // distance to plane y = const (camera height)
    float d_min = sdPlane(p, plane);
    material = plane.material;

    // base
    float d_box   = sdBoxRounded(p, box1);
    // cut off bottom by plane
    d_box = max(d_box, -(p.y-box1.position.y));
    if (d_min > d_box){
        d_min = d_box;
        material = box1.material;
    }

    // wired bar
    vec3 ps = p;
    // two symmentric wires relatively to the z-axis
    ps.z = abs(ps.z);
    float d_wire = sdBox2D(ps, box2);
    // cut off bottom by plane
    d_wire = max(d_wire, -(p.y-box2.position.y));
    if (d_min > d_wire){
        d_min = d_wire;
        material = box2.material;
    }

    // ball
    float angle0 = 40.*sin(4.*iTime);
    float angle1 = max(0., angle0);
    float angle5 = min(0., angle0);
    Material mat0;
    // ball1
    float d_ball1 = sdBall(mat0, p, sphere1, angle1);
    if (d_min > d_ball1){
        d_min = d_ball1;
        material = mat0;
    }
    // ball2
    float d_ball2 = sdBall(mat0, p, sphere2, (angle1 + angle0)*.05);
    if (d_min > d_ball2){
        d_min = d_ball2;
        material = mat0;
    }
    // ball3
    float d_ball3 = sdBall(mat0, p, sphere3, angle0*.05);
    if (d_min > d_ball3){
        d_min = d_ball3;
        material = mat0;
    }
    // ball4
    float d_ball4 = sdBall(mat0, p, sphere4, (angle5 + angle0)*.05);
    if (d_min > d_ball4){
        d_min = d_ball4;
        material = mat0;
    }
    // ball5
    float d_ball5 = sdBall(mat0, p, sphere5, angle5);
    if (d_min > d_ball5){
        d_min = d_ball5;
        material = mat0;
    }

    return d_min;
}
vec3 param_ray(Ray ray, float t){
    return ray.origin + t*ray.direction;
}
Material RayMarch(Ray ray, inout float d){
    Material material = material_backgroud;
    for(int i = 0; i < MAX_STEPS; i++){
        vec3 p = param_ray(ray, d);
        float d0 = GetDistance(material, p);
        d += d0;
        if(d0 < SURFACE_DISTANCE || abs(d) > MAX_DISTANCE) break;
    }
    return material;
}

vec3 GetNormal(vec3 p){
    vec2 e = vec2(EPS, 0);
    Material material;
    float d = GetDistance(material, p);
    return normalize(d - vec3(GetDistance(material, p-e.xyy),
                              GetDistance(material, p-e.yxy),
                              GetDistance(material, p-e.yyx)));
}

Material BackGround(vec3 r){
    Material material = material_backgroud;
//    float y = (r.y + 1.)*0.5;
    float y = atan(r.y,length(r.xz))/PI;
    material.ambient += 3.*y*vec3(.1, .4, 1);
    return material;
}

float fresnel(float cosine, float RI)
{
//    /*
    float r0 = (1. - RI)/(1. + RI);
    r0 = r0 * r0;
    return r0 + (1. - r0)*pow(1. - cosine, 5.);
//    */
//    return pow(1. - cosine, 5.);
}
vec3 GetColor(Ray ray, vec3 normal, Material material, Light light){
    // direction to light source
    vec3 light_direction = normalize(light.position - ray.origin);

    //ambient
    vec3 intencity = material.ambient;

    float d = 0.;
    // is there an obstacle on the light path
    RayMarch(Ray(ray.origin, light_direction), d);
    if(d > MAX_DISTANCE){
        // diffuse
        intencity += material.diffuse*clamp(dot(normal, light_direction), 0., 1.);
        // specular
        intencity += material.specular*
            pow(clamp(dot(normal, normalize(light_direction + ray.direction)), 0., 1.),
                material.spec_gamma);
    }
    return intencity;
}
vec3 Render(Ray ray){
    float d;
    vec3 color = vec3(0.);
    vec3 p;
    vec3 normal;
    vec3 reflection = vec3(1);

    for(int depth = 0; depth < MAX_DEPTH; depth++){
        d = 0.;
        Material material = RayMarch(ray, d);
        p = param_ray(ray, d);

        if(d > MAX_DISTANCE){
            // first hit
            if (depth == 0)
                return BackGround(p).ambient;
            else
                return color + 0.*reflection*BackGround(p).ambient;
        }

        normal = GetNormal(p); // normal to object
        // new ray -> source on surface
        ray.origin = p + normal*2.*SURFACE_DISTANCE;
        if (material.transparent){

        }
        if(material.fresnel){
            material.reflection = fresnel(dot(normal, ray.direction), material.n);
        }
        color += reflection * GetColor(ray, normal, material, light);
        reflection *= material.reflection;

        // new ray -> reflected ray
        ray.direction = reflect(ray.direction, normal);
    }

    return color;
}

void camera_rotation(Camera camera, vec2 angles, vec2 coord, out vec3 camera_look_from, out vec3 camera_direction){
    mat2 rot;
    camera_look_from = camera.look_from;
    vec3 camera_look_at = camera.look_at;
    camera_direction = camera_look_from - camera_look_at;
    vec3 horizontal = camera.horizontal;
    vec3 vertical = camera.vertical;

    // camera rotation
    camera_direction = rotate(camera_direction, angles.x, angles.y);
    horizontal = normalize(cross(camera_direction, vec3(0,1,0)));
    vertical = normalize(cross(horizontal, camera_direction));

    camera_look_from = camera_look_at - camera_direction;

    camera_direction = normalize(camera_direction + camera.FOV*(horizontal*coord.x + vertical*coord.y));
}

//out vec4 FragColor;
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 coord = (2.*fragCoord.xy - iResolution.xy)/iResolution.x;
    vec2 m = iMouse.xy/iResolution.xy;

    // // move light
    light.position.x += 3.*sin(0.55*iTime);
    light.position.z += 3.*cos(0.5*iTime);

    // move camera
    vec3 camera_look_from, camera_direction;
    camera_rotation(camera, vec2(-m.x*PI, -m.y*PI_TWO), coord, camera_look_from, camera_direction);

    Ray ray = Ray(camera_look_from, camera_direction);
    vec3 color = Render(ray);

    color = pow(color, vec3(.4545));	// gamma correction


    // Output to screen
    fragColor = vec4(color, 1.0);
 }
